1	package indexroom
2	
3	import (
4		"crypto/hmac"
5		"crypto/rand"
6		"crypto/sha256"
7		"encoding/base64"
8		"encoding/binary"
9		"encoding/hex"
10		"encoding/json"
11		"errors"
12		"fmt"
13		"sort"
14		"strings"
15		"sync/atomic"
16	)
17	
18	// ErrInvalidArgument marks a rejected query: out-of-range heights or page
19	// size, a malformed cursor, a cursor issued by another index instance, or
20	// continuation conditions that differ from the first page. It never reports
21	// chain data problems; use errors.Is to tell it apart from ErrQueryChanged.
22	var ErrInvalidArgument = errors.New("indexroom: invalid query argument")
23	
24	// ErrQueryChanged marks a continuation whose pinned range no longer matches
25	// the first page: a block in the range was replaced (even under the same
26	// hash, and even if only its timestamp changed) or the chain was shortened
27	// below the pinned upper bound. No results are returned; the caller must
28	// restart from a first-page query.
29	var ErrQueryChanged = errors.New("indexroom: query data changed")
30	
31	// queryTxsHookLocked is a test-only rendezvous invoked once per QueryTxs
32	// call while index.mu is held: for a first page after the tip-bound height has
33	// been resolved (and non-empty ranges only), and for a continuation only after
34	// every pinned-range check has passed, so the call is committed to a
35	// successful page against the chain state in effect. It is nil in production;
36	// reorg regression tests park a query here to force a concurrent Reorg to wait
37	// (or park the Reorg and make the query wait), making the "one complete
38	// main-chain view per page" observation deterministic instead of relying on
39	// scheduling luck.
40	var queryTxsHookLocked func(from, to int64, continuation bool)
41	
42	const (
43		// DefaultPageSize is the page length when TxQuery.PageSize is zero.
44		DefaultPageSize = 100
45		// MaxPageSize is the largest accepted TxQuery.PageSize.
46		MaxPageSize = 1000
47	)
48	
49	// TxQuery describes a transaction lookup against the main chain.
50	type TxQuery struct {
51		// From and To bound the searched heights, both inclusive. A zero From
52		// starts at height 1. A zero To pins the chain tip seen by the first
53		// page; an explicit To above the tip is clamped to it. Explicit heights
54		// must be positive, and an explicit To must not be below From.
55		From int64
56		To   int64
57		// TxIDs restricts results to these identifiers, matched by exact string
58		// comparison; an empty slice disables the filter. Duplicates and order
59		// inside the slice are irrelevant.
60		TxIDs []string
61		// PageSize picks the page length, 1..MaxPageSize; zero means
62		// DefaultPageSize. It may change between pages of the same query.
63		PageSize int
64		// Cursor continues an earlier query; empty asks for the first page. On
65		// continuation the height range and TxIDs must equal the first page's.
66		Cursor string
67	}
68	
69	// TxHit is one transaction occurrence on the main chain. The same
70	// identifier appears once per occurrence, in different blocks or several
71	// times inside one block.
72	type TxHit struct {
73		Height    int64
74		BlockHash string
75		TxID      string
76		Position  int
77	}
78	
79	// TxPage is one page of query results together with statistics over the
80	// whole filtered range. Hits are ordered by height, then by position inside
81	// the block.
82	type TxPage struct {
83		Hits []TxHit
84		// TotalMatches counts every matching occurrence in the pinned range; it
85		// does not change between pages of the same query.
86		TotalMatches int64
87		// MatchedBlocks counts the blocks holding at least one match.
88		MatchedBlocks int64
89		// ToHeight is the upper bound pinned by the first page: the requested
90		// To clamped to the chain tip seen at that moment.
91		ToHeight int64
92		// NextCursor continues the query; empty means this is the last page.
93		NextCursor string
94	}
95	
96	// QueryTxs searches the main chain for transaction occurrences matching the
97	// query. Every call observes one complete chain state: concurrent Append or
98	// Reorg calls never leak into a page, and the returned records are copies
99	// the caller may freely mutate. The query itself never modifies the index.
100	//
101	// The first page (empty Cursor) pins the filtered range and returns a
102	// continuation cursor while more results remain. Continuations reuse the
103	// pinned range — blocks appended above it are invisible to the query — and
104	// succeed as long as every block inside the range still matches the first
105	// page; otherwise they fail with ErrQueryChanged.
106	func (index *Index) QueryTxs(query TxQuery) (TxPage, error) {
107		pageSize, err := normalizePageSize(query.PageSize)
108		if err != nil {
109			return TxPage{}, err
110		}
111		if query.Cursor != "" {
112			return index.continueQuery(query, pageSize)
113		}
114		return index.firstQuery(query, pageSize)
115	}
116	
117	func normalizePageSize(size int) (int, error) {
118		if size == 0 {
119			return DefaultPageSize, nil
120		}
121		if size < 0 || size > MaxPageSize {
122			return 0, fmt.Errorf("%w: page size must be between 1 and %d", ErrInvalidArgument, MaxPageSize)
123		}
124		return size, nil
125	}
126	
127	// normalizeRange validates the requested heights and resolves the zero From
128	// default. A zero To is left as-is; it is resolved against the chain tip
129	// while holding the lock.
130	func normalizeRange(from, to int64) (int64, int64, error) {
131		if from < 0 {
132			return 0, 0, fmt.Errorf("%w: from height must be positive", ErrInvalidArgument)
133		}
134		if to < 0 {
135			return 0, 0, fmt.Errorf("%w: to height must be positive", ErrInvalidArgument)
136		}
137		if from == 0 {
138			from = 1
139		}
140		if to != 0 && to < from {
141			return 0, 0, fmt.Errorf("%w: to height is below from height", ErrInvalidArgument)
142		}
143		return from, to, nil
144	}
145	
146	func (index *Index) firstQuery(query TxQuery, pageSize int) (TxPage, error) {
147		from, to, err := normalizeRange(query.From, query.To)
148		if err != nil {
149			return TxPage{}, err
150		}
151	
152		index.mu.Lock()
153		defer index.mu.Unlock()
154	
155		if to == 0 || to > index.Tip {
156			to = index.Tip
157		}
158		page := TxPage{Hits: []TxHit{}, ToHeight: to}
159		if from > to {
160			// Empty index or a start above the tip: a successful empty result.
161			return page, nil
162		}
163		if queryTxsHookLocked != nil {
164			queryTxsHookLocked(from, to, false)
165		}
166		hits, total, blocks := index.scanPageLocked(from, to, query.TxIDs, 0, pageSize)
167		return index.buildPageLocked(query, from, to, hits, total, blocks, 0, pageSize), nil
168	}
169	
170	func (index *Index) continueQuery(query TxQuery, pageSize int) (TxPage, error) {
171		payload, err := index.decodeCursor(query.Cursor)
172		if err != nil {
173			return TxPage{}, err
174		}
175		from, _, err := normalizeRange(query.From, query.To)
176		if err != nil {
177			return TxPage{}, err
178		}
179		if from != payload.From {
180			return TxPage{}, fmt.Errorf("%w: from height differs from the first page", ErrInvalidArgument)
181		}
182		if query.To != payload.ReqTo {
183			return TxPage{}, fmt.Errorf("%w: to height differs from the first page", ErrInvalidArgument)
184		}
185		if got := hex.EncodeToString(hashTxSet(query.TxIDs)); got != payload.Set {
186			return TxPage{}, fmt.Errorf("%w: transaction filter differs from the first page", ErrInvalidArgument)
187		}
188	
189		index.mu.Lock()
190		defer index.mu.Unlock()
191	
192		if index.Tip < payload.To {
193			return TxPage{}, fmt.Errorf("%w: chain tip %d is below the pinned upper bound %d",
194				ErrQueryChanged, index.Tip, payload.To)
195		}
196		if got := hex.EncodeToString(index.fingerprintLocked(payload.From, payload.To)); got != payload.FP {
197			return TxPage{}, fmt.Errorf("%w: blocks in the pinned range differ from the first page", ErrQueryChanged)
198		}
199		if queryTxsHookLocked != nil {
200			queryTxsHookLocked(payload.From, payload.To, true)
201		}
202		// Re-scan the still-identical pinned range: the cursor records the
203		// absolute offset, but no full match list is kept between pages.
204		hits, total, blocks := index.scanPageLocked(payload.From, payload.To, query.TxIDs, payload.Off, pageSize)
205		if payload.Off > total {
206			return TxPage{}, fmt.Errorf("%w: cursor offset is beyond the pinned results", ErrQueryChanged)
207		}
208		return index.buildPageLocked(query, payload.From, payload.To, hits, total, blocks, payload.Off, pageSize), nil
209	}
210	
211	// buildPageLocked assembles one page from a page-sized scan and mints the
212	// continuation cursor when matches remain. total and blocks describe the
213	// whole pinned range; hits holds only the window [offset, offset+pageSize).
214	// The caller must hold index.mu.
215	func (index *Index) buildPageLocked(query TxQuery, from, to int64, hits []TxHit, total, blocks, offset int64, pageSize int) TxPage {
216		page := TxPage{
217			Hits:          hits,
218			TotalMatches:  total,
219			MatchedBlocks: blocks,
220			ToHeight:      to,
221		}
222		if offset+int64(len(hits)) < total {
223			page.NextCursor = index.encodeCursor(cursorPayload{
224				V:     1,
225				From:  from,
226				ReqTo: query.To,
227				To:    to,
228				Set:   hex.EncodeToString(hashTxSet(query.TxIDs)),
229				FP:    hex.EncodeToString(index.fingerprintLocked(from, to)),
230				Off:   offset + int64(len(hits)),
231			})
232		}
233		return page
234	}
235	
236	// scanPageLocked walks the whole pinned range once in height/position order,
237	// counting every matching occurrence and every block holding one, while
238	// retaining only the page window [offset, offset+pageSize) in a pre-sized
239	// slice: at most pageSize TxHit records, independent of how many matches the
240	// whole range holds. The caller must hold index.mu.
241	func (index *Index) scanPageLocked(from, to int64, txIDs []string, offset int64, pageSize int) (hits []TxHit, total, blocks int64) {
242		var filter map[string]struct{}
243		if len(txIDs) > 0 {
244			filter = make(map[string]struct{}, len(txIDs))
245			for _, id := range txIDs {
246				filter[id] = struct{}{}
247			}
248		}
249		hits = make([]TxHit, 0, pageSize)
250		for height := from; height <= to; height++ {
251			block := index.Blocks[height]
252			matched := false
253			for position, tx := range block.Txs {
254				if filter != nil {
255					if _, ok := filter[tx]; !ok {
256						continue
257					}
258				}
259				if total >= offset && int64(len(hits)) < int64(pageSize) {
260					hits = append(hits, TxHit{Height: height, BlockHash: block.Hash, TxID: tx, Position: position})
261				}
262				total++
263				matched = true
264			}
265			if matched {
266				blocks++
267			}
268		}
269		return hits, total, blocks
270	}
271	
272	// fingerprintLocked hashes the exact content of every block in [from, to]:
273	// height, hash, parent, the ordered transaction list, and the timestamp
274	// (distinguishing a missing timestamp from zero). The caller must hold
275	// index.mu.
276	func (index *Index) fingerprintLocked(from, to int64) []byte {
277		h := sha256.New()
278		var lenBuf [8]byte
279		writeString := func(s string) {
280			binary.BigEndian.PutUint64(lenBuf[:], uint64(len(s)))
281			h.Write(lenBuf[:])
282			h.Write([]byte(s))
283		}
284		for height := from; height <= to; height++ {
285			block := index.Blocks[height]
286			binary.BigEndian.PutUint64(lenBuf[:], uint64(block.Height))
287			h.Write(lenBuf[:])
288			writeString(block.Hash)
289			writeString(block.Parent)
290			binary.BigEndian.PutUint64(lenBuf[:], uint64(len(block.Txs)))
291			h.Write(lenBuf[:])
292			for _, tx := range block.Txs {
293				writeString(tx)
294			}
295			if block.Time == nil {
296				h.Write([]byte{0})
297			} else {
298				h.Write([]byte{1})
299				binary.BigEndian.PutUint64(lenBuf[:], uint64(*block.Time))
300				h.Write(lenBuf[:])
301			}
302		}
303		return h.Sum(nil)
304	}
305	
306	// hashTxSet hashes the deduplicated, sorted identifier set so that cursor
307	// validation is insensitive to duplicates and ordering.
308	func hashTxSet(txIDs []string) []byte {
309		unique := make(map[string]struct{}, len(txIDs))
310		sorted := make([]string, 0, len(txIDs))
311		for _, id := range txIDs {
312			if _, ok := unique[id]; ok {
313				continue
314			}
315			unique[id] = struct{}{}
316			sorted = append(sorted, id)
317		}
318		sort.Strings(sorted)
319		h := sha256.New()
320		var lenBuf [8]byte
321		for _, id := range sorted {
322			binary.BigEndian.PutUint64(lenBuf[:], uint64(len(id)))
323			h.Write(lenBuf[:])
324			h.Write([]byte(id))
325		}
326		return h.Sum(nil)
327	}
328	
329	// cursorPayload is the signed state carried between pages of one query.
330	type cursorPayload struct {
331		V     int    `json:"v"`
332		From  int64  `json:"from"`
333		ReqTo int64  `json:"reqTo"`
334		To    int64  `json:"to"`
335		Set   string `json:"set"`
336		FP    string `json:"fp"`
337		Off   int64  `json:"off"`
338	}
339	
340	const cursorPrefix = "q1"
341	
342	// encodeCursor serializes the payload and signs it with the per-instance
343	// key, so cursors are self-contained yet unusable on any other index.
344	func (index *Index) encodeCursor(payload cursorPayload) string {
345		raw, err := json.Marshal(payload)
346		if err != nil {
347			panic(err) // cursorPayload only contains marshalable fields
348		}
349		body := base64.RawURLEncoding.EncodeToString(raw)
350		mac := hmac.New(sha256.New, index.key[:])
351		mac.Write([]byte(cursorPrefix + "." + body))
352		sig := base64.RawURLEncoding.EncodeToString(mac.Sum(nil))
353		return cursorPrefix + "." + body + "." + sig
354	}
355	
356	// decodeCursor verifies the signature before trusting any payload field;
357	// every failure is an argument error, never a data-changed error.
358	func (index *Index) decodeCursor(cursor string) (cursorPayload, error) {
359		var payload cursorPayload
360		parts := strings.Split(cursor, ".")
361		if len(parts) != 3 || parts[0] != cursorPrefix {
362			return payload, fmt.Errorf("%w: malformed cursor", ErrInvalidArgument)
363		}
364		sig, err := base64.RawURLEncoding.DecodeString(parts[2])
365		if err != nil {
366			return payload, fmt.Errorf("%w: malformed cursor", ErrInvalidArgument)
367		}
368		mac := hmac.New(sha256.New, index.key[:])
369		mac.Write([]byte(parts[0] + "." + parts[1]))
370		if !hmac.Equal(sig, mac.Sum(nil)) {
371			return payload, fmt.Errorf("%w: cursor not recognized by this index", ErrInvalidArgument)
372		}
373		raw, err := base64.RawURLEncoding.DecodeString(parts[1])
374		if err != nil {
375			return payload, fmt.Errorf("%w: malformed cursor", ErrInvalidArgument)
376		}
377		if err := json.Unmarshal(raw, &payload); err != nil || payload.V != 1 {
378			return payload, fmt.Errorf("%w: malformed cursor", ErrInvalidArgument)
379		}
380		return payload, nil
381	}
382	
383	var keyFallback atomic.Uint64
384	
385	// newKey derives the per-instance cursor signing key. crypto/rand is not
386	// expected to fail; the counter fallback still keeps keys unique per
387	// instance so cursors never validate across indexes.
388	func newKey() [32]byte {
389		var key [32]byte
390		if _, err := rand.Read(key[:]); err != nil {
391			binary.BigEndian.PutUint64(key[:8], keyFallback.Add(1))
392		}
393		return key
394	}
